import os
import uuid
from typing import Dict, List
from collections import defaultdict
import threading

from flask import Flask, request, jsonify
from flask_cors import CORS
from cerebras.cloud.sdk import Cerebras
from exa_py import Exa

app = Flask(__name__, static_folder='static')
CORS(app)

CEREBRAS_API_KEY = os.getenv("CEREBRAS_API_KEY")
EXA_API_KEY = os.getenv("EXA_API_KEY")

if CEREBRAS_API_KEY is None or EXA_API_KEY is None:
    raise ValueError("CEREBRAS_API_KEY és EXA_API_KEY környezeti változók beállítása kötelező!")

try:
    cerebras_client = Cerebras(api_key=CEREBRAS_API_KEY)
except Exception as e:
    raise ValueError(f"Invalid CEREBRAS_API_KEY: {e}")

try:
    exa_client = Exa(api_key=EXA_API_KEY)
except Exception as e:
    raise ValueError(f"Invalid EXA_API_KEY: {e}")

chat_histories: Dict[str, List[dict]] = defaultdict(list)
research_tasks: Dict[str, dict] = {}

CHAT_MODEL = "gpt-oss-120b"
RESEARCH_MODEL = "qwen-3-235b-a22b-thinking-2507"

@app.route('/api/chat/history/<session_id>', methods=['GET'])
def get_chat_history(session_id: str):
    session_id = session_id.strip()
    if not session_id:
        return jsonify({"error": "Invalid session_id"}), 400
    messages = chat_histories.get(session_id, [])
    return jsonify({"messages": messages})

@app.route('/api/chat/history/<session_id>', methods=['POST'])
def save_chat_message(session_id: str):
    session_id = session_id.strip()
    if not session_id:
        return jsonify({"error": "Invalid session_id"}), 400
    if not request.is_json:
        return jsonify({"error": "Invalid JSON"}), 400
    data = request.json
    message = data.get('message')
    if not isinstance(message, dict) or 'role' not in message or 'content' not in message:
        return jsonify({"error": "Invalid message format"}), 400
    chat_histories[session_id].append(message)
    return jsonify({"success": True})

@app.route('/api/chat/history/<session_id>', methods=['DELETE'])
def clear_chat_history(session_id: str):
    session_id = session_id.strip()
    if session_id in chat_histories:
        del chat_histories[session_id]
    return jsonify({"success": True})

@app.route('/api/chat', methods=['POST'])
def chat():
    try:
        if not request.is_json:
            return jsonify({"error": "Invalid JSON"}), 400
        data = request.json
        messages = data.get('messages', [])
        if not messages or not isinstance(messages, list):
            return jsonify({"error": "Nincs üzenet megadva"}), 400
        temperature = data.get('temperature', 0.09)
        response = cerebras_client.chat.completions.create(
            model=CHAT_MODEL,
            messages=messages,
            temperature=temperature,
            top_p=0.06,
            max_completion_tokens=2048,
            reasoning_effort="low"
        )
        return jsonify({
            "choices": [{
                "message": {
                    "role": "assistant",
                    "content": response.choices[0].message.content
                }
            }]
        })
    except Exception as e:
        print(f"Chat hiba: {str(e)}")
        return jsonify({"error": f"Hiba történt: {str(e)}"}), 500

@app.route('/api/research/create', methods=['POST'])
def create_research():
    try:
        if not request.is_json:
            return jsonify({"error": "Invalid JSON"}), 400
        data = request.json
        goal = data.get('goal', '').strip()
        if not goal:
            return jsonify({"error": "Goal required"}), 400
        task_id = uuid.uuid4()
        research_tasks[task_id] = {
            "id": str(task_id),
            "goal": goal,
            "status": "Indítás...",
            "progress": 0,
            "sub_agents": [
                {"name": "Keresési Ágent", "status": "Várakozás..."},
                {"name": "Elemző Ágent", "status": "Várakozás..."},
                {"name": "Jelentés Író Ágent", "status": "Várakozás..."}
            ],
            "sources": [],
            "report": "",
            "search_params": {
                "search_type": data.get('search_type', 'auto'),
                "category": data.get('category'),
                "user_location": data.get('user_location'),
                "start_published_date": data.get('start_published_date'),
                "end_published_date": data.get('end_published_date'),
                "start_crawl_date": data.get('start_crawl_date'),
                "end_crawl_date": data.get('end_crawl_date'),
                "include_domains": data.get('include_domains'),
                "exclude_domains": data.get('exclude_domains'),
                "include_text": data.get('include_text'),
                "exclude_text": data.get('exclude_text'),
                "full_text": data.get('full_text', False),
                "ai_summary": data.get('ai_summary', False),
                "subpages": data.get('subpages', False),
                "subpage_target": data.get('subpage_target', 3),
                "livecrawl": data.get('livecrawl', 'fallback'),
                "livecrawl_timeout": data.get('livecrawl_timeout'),
                "links": data.get('links', False)
            }
        }
        thread = threading.Thread(target=run_research_task, args=(task_id,), daemon=True)
        thread.start()
        return jsonify({"task_id": str(task_id)})
    except Exception as e:
        print(f"Kutatás létrehozási hiba: {str(e)}")
        return jsonify({"error": str(e)}), 500

@app.route('/api/research/<task_id>', methods=['GET'])
def get_research_status(task_id: str):
    task_id = task_id.strip()
    if not task_id:
        return jsonify({"error": "Invalid task_id"}), 400
    task = research_tasks.get(task_id)
    if not task:
        return jsonify({"error": "Feladat nem található"}), 404
    return jsonify(task)

def run_research_task(task_id):
    task = research_tasks.get(task_id)
    if not task:
        return
    try:
        task["status"] = "Keresési lekérdezések generálása..."
        task["progress"] = 10
        task["sub_agents"][0]["status"] = "Aktív"
        queries = generate_search_queries(task["goal"])
        task["status"] = "Web keresés folyamatban..."
        task["progress"] = 30
        task["sub_agents"][0]["status"] = "Web források gyűjtése..."
        sources = search_web(queries, task["search_params"])
        task["sources"] = sources
        task["sub_agents"][0]["status"] = "Befejezve"
        task["status"] = "Tartalom elemzése..."
        task["progress"] = 60
        task["sub_agents"][1]["status"] = "Aktív - Források feldolgozása..."
        analyzed_content = analyze_sources(sources, task["goal"])
        task["sub_agents"][1]["status"] = "Befejezve"
        task["status"] = "Jelentés készítése..."
        task["progress"] = 80
        task["sub_agents"][2]["status"] = "Aktív - Jelentés írása..."
        report = generate_report(task["goal"], analyzed_content, sources)
        task["report"] = report
        task["sub_agents"][2]["status"] = "Befejezve"
        task["status"] = "completed"
        task["progress"] = 100
    except Exception as e:
        print(f"Kutatási hiba: {str(e)}")
        task["status"] = "error"
        task["report"] = f"Hiba történt: {str(e)}"

def generate_search_queries(goal: str) -> List[str]:
    try:
        prompt = f"""Generálj 3-5 precíz keresési lekérdezést a következő kutatási célhoz:

Kutatási cél: {goal}

Adj vissza csak a lekérdezéseket, soronként egyet, magyarázat nélkül."""
        response = cerebras_client.chat.completions.create(
            model=RESEARCH_MODEL,
            messages=[{"role": "user", "content": prompt}],
            temperature=0.09,
            top_p=0.06,
            max_completion_tokens=500
        )
        queries_text = response.choices[0].message.content.strip()
        queries = [q.strip() for q in queries_text.splitlines() if q.strip() and not q.strip().startswith('#')]
        return queries[:5]
    except Exception as e:
        print(f"Lekérdezés generálási hiba: {str(e)}")
        return [goal]

def search_web(queries: List[str], search_params: dict) -> List[dict]:
    all_sources = []
    try:
        for query in queries:
            search_kwargs = {
                "query": query,
                "num_results": 10,
                "use_autoprompt": True,
                "type": search_params.get("search_type", "auto")
            }
            if search_params.get("category"):
                search_kwargs["category"] = search_params["category"]
            if search_params.get("start_published_date"):
                search_kwargs["start_published_date"] = search_params["start_published_date"]
            if search_params.get("end_published_date"):
                search_kwargs["end_published_date"] = search_params["end_published_date"]
            if search_params.get("include_domains"):
                search_kwargs["include_domains"] = search_params["include_domains"]
            if search_params.get("exclude_domains"):
                search_kwargs["exclude_domains"] = search_params["exclude_domains"]
            text_config = True if search_params.get("full_text", False) else {"max_characters": 1000}
            contents_kwargs = {
                "text": text_config,
                "highlights": True
            }
            if search_params.get("ai_summary", False):
                contents_kwargs["summary"] = True
            results = exa_client.search_and_contents(**search_kwargs, **contents_kwargs)
            for result in results.results:
                source = {
                    "url": result.url,
                    "title": result.title,
                    "text": getattr(result, 'text', ""),
                    "summary": getattr(result, 'summary', ""),
                    "published_date": getattr(result, 'published_date', None)
                }
                all_sources.append(source)
        seen_urls = set()
        unique_sources = [source for source in all_sources if not (source["url"] in seen_urls or seen_urls.add(source["url"]))]
        return unique_sources[:30]
    except Exception as e:
        print(f"Web keresési hiba: {str(e)}")
        return []

def analyze_sources(sources: List[dict], goal: str) -> str:
    try:
        source_parts = []
        for i, source in enumerate(sources[:15], 1):
            text = source.get("text", "") or source.get("summary", "")
            if text:
                source_parts.append(f"\n\n--- FORRÁS {i}: {source['title']} ---\n{text[:2000]}")
        sources_text = "".join(source_parts)
        prompt = f"""Elemezd az alábbi forrásokat a következő kutatási cél alapján:

Kutatási cél: {goal}

Források:
{sources_text}

Add meg a legfontosabb megállapításokat, tényeket és összefüggéseket strukturáltan."""
        response = cerebras_client.chat.completions.create(
            model=RESEARCH_MODEL,
            messages=[{"role": "user", "content": prompt}],
            temperature=0.09,
            top_p=0.06,
            max_completion_tokens=3000
        )
        return response.choices[0].message.content
    except Exception as e:
        print(f"Elemzési hiba: {str(e)}")
        return "Nem sikerült elemezni a forrásokat."

def generate_report(goal: str, analyzed_content: str, sources: List[dict]) -> str:
    try:
        sources_list = "\n".join([f"[{i}] {s['title']} - {s['url']}" for i, s in enumerate(sources[:20], 1)])
        prompt = f"""Készíts részletes, szakmai kutatási jelentést az alábbi adatok alapján:

KUTATÁSI CÉL:
{goal}

ELEMZETT TARTALOM:
{analyzed_content}

FORRÁSOK:
{sources_list}

A jelentés legyen:
- Strukturált fejezetekkel
- Minimum 800 szó
- Tartalmazza a legfontosabb megállapításokat
- Konkrét adatokat és tényeket
- Következtetéseket és ajánlásokat
- Magyar nyelven
- Szakmai stílusban

A jelentés végén add meg a használt forrásokat számozott hivatkozásként."""
        response = cerebras_client.chat.completions.create(
            model=RESEARCH_MODEL,
            messages=[{"role": "user", "content": prompt}],
            temperature=0.09,
            top_p=0.06,
            max_completion_tokens=4000
        )
        return response.choices[0].message.content
    except Exception as e:
        print(f"Jelentés generálási hiba: {str(e)}")
        return "Nem sikerült generálni a jelentést."

