                <button id="send-button" disabled>
                    <svg id="icon-send" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                        <line x1="22" y1="2" x2="11" y2="13"></line>
                        <polygon points="22,2 15,22 11,13 2,9 22,2"></polygon>
                    </svg>
                    <svg id="icon-research" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                        <circle cx="11" cy="11" r="8"></circle>
                        <line x1="21" y1="21" x2="16.65" y2="16.65"></line>
                    </svg>
                </button>
            </div>
        </footer>
    </div>
    <div id="research-view">
        <header class="frosted-header" id="research-header">
            <button id="research-back-button">
                <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                    <line x1="19" y1="12" x2="5" y2="12"></line>
                    <polyline points="12,19 5,12 12,5"></polyline>
                </svg>
                <span>Vissza</span>
            </button>
            <h1 id="research-title">Kutatás</h1>
        </header>
        <div id="research-content">
            <div class="research-section-title">Állapot</div>
            <div class="agent-grid" id="agent-grid"></div>
            <div class="research-section-title">Források</div>
            <div id="sources-list"></div>
            <div class="research-section-title">Jelentés</div>
            <div id="report-content"></div>
        </div>
    </div>
    <div id="research-options-modal-overlay">
        <div id="research-options-modal">
            <div class="modal-handle"></div>
            <h2>Új kutatási feladat</h2>
            <div id="research-goal-summary">Írd be a kutatási célt az üzenetbe!</div>
            <div class="form-group">
                <label for="research-goal">Kutatási cél:</label>
                <input type="text" id="research-goal" placeholder="Például: A mesterséges intelligencia hatása a munkapiacra" />
            </div>
            <button id="toggle-advanced-options">Haladó opciók megjelenítése</button>
            <div id="advanced-options-container">
                <div class="form-group">
                    <label for="search-type">Keresés típusa:</label>
                    <select id="search-type">
                        <option value="keyword">Kulcsszó alapú</option>
                        <option value="neural">Neurális</option>
                    </select>
                </div>
                <div class="form-group">
                    <label for="start-published-date">Kezdő dátum (közzététel):</label>
                    <input type="date" id="start-published-date" />
                </div>
                <div class="form-group">
                    <label for="end-published-date">Befejező dátum (közzététel):</label>
                    <input type="date" id="end-published-date" />
                </div>
                <div class="form-group">
                    <label for="include-domains">Beleértendő domainek (vesszővel elválasztva):</label>
                    <input type="text" id="include-domains" placeholder="example.com, wikipedia.org" />
                </div>
                <div class="form-group">
                    <label for="full-text">Teljes szöveg:</label>
                    <input type="checkbox" id="full-text" />
                </div>
                <div class="form-group">
                    <label for="ai-summary">AI összefoglaló:</label>
                    <input type="checkbox" id="ai-summary" />
                </div>
            </div>
            <button id="submit-research-task">Kutatás indítása</button>
            <button id="cancel-research-task">Mégse</button>
        </div>
    </div>
    <script>
        (function() {
            const API_BASE = '/api';
            let currentSessionId = localStorage.getItem('sessionId') || generateUUID();
            localStorage.setItem('sessionId', currentSessionId);
            let currentMode = 'chat';
            let currentResearchId = null;
            let statusInterval = null;
            let isTyping = false;

            function generateUUID() {
                return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
                    const r = Math.random() * 16 | 0;
                    const v = c === 'x' ? r : (r & 0x3 | 0x8);
                    return v.toString(16);
                });
            }

            function initBackground() {
                const canvas = document.getElementById('canvas-bg');
                if (!canvas) return;
                const scene = new THREE.Scene();
                const camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
                const renderer = new THREE.WebGLRenderer({ canvas, alpha: true, antialias: true });
                renderer.setSize(window.innerWidth, window.innerHeight);
                renderer.setPixelRatio(window.devicePixelRatio);
                const geometry = new THREE.BufferGeometry();
                const vertices = [];
                for (let i = 0; i < 500; i++) {
                    vertices.push((Math.random() - 0.5) * 2000);
                    vertices.push((Math.random() - 0.5) * 2000);
                    vertices.push((Math.random() - 0.5) * 2000);
                }
                geometry.setAttribute('position', new THREE.BufferAttribute(new Float32Array(vertices), 3));
                const material = new THREE.PointsMaterial({ color: 0x007aff, size: 2, sizeAttenuation: true });
                const points = new THREE.Points(geometry, material);
                scene.add(points);
                camera.position.z = 100;
                function animate() {
                    requestAnimationFrame(animate);
                    points.rotation.x += 0.0001;
                    points.rotation.y += 0.0001;
                    renderer.render(scene, camera);
                }
                animate();
                window.addEventListener('resize', function() {
                    const width = window.innerWidth;
                    const height = window.innerHeight;
                    camera.aspect = width / height;
                    camera.updateProjectionMatrix();
                    renderer.setSize(width, height);
                });
            }

            function showError(message) {
                const chatHistory = document.getElementById('chat-history');
                const errorEl = document.createElement('div');
                errorEl.className = 'message ai error';
                errorEl.textContent = message;
                chatHistory.appendChild(errorEl);
                chatHistory.scrollTop = chatHistory.scrollHeight;
            }

            async function sendMessage() {
                const input = document.getElementById('message-input');
                const messageText = input.value.trim();
                if (!messageText) return;
                const chatHistory = document.getElementById('chat-history');
                const userMessageEl = document.createElement('div');
                userMessageEl.className = 'message user';
                userMessageEl.textContent = messageText;
                chatHistory.appendChild(userMessageEl);
                input.value = '';
                updateSendButton();
                chatHistory.scrollTop = chatHistory.scrollHeight;
                const message = { role: 'user', content: messageText };
                try {
                    await fetch(`${API_BASE}/chat/history/${currentSessionId}`, {
                        method: 'POST',
                        headers: { 'Content-Type': 'application/json' },
                        body: JSON.stringify({ message })
                    });
                } catch (e) {
                    console.error('Failed to save message:', e);
                }
                const typingEl = document.createElement('div');
                typingEl.className = 'message ai typing-indicator';
                typingEl.innerHTML = '<span class="typing-dot"></span><span class="typing-dot"></span><span class="typing-dot"></span>';
                chatHistory.appendChild(typingEl);
                chatHistory.scrollTop = chatHistory.scrollHeight;
                try {
                    const historyResponse = await fetch(`${API_BASE}/chat/history/${currentSessionId}`);
                    if (!historyResponse.ok) throw new Error('Failed to fetch history');
                    const historyData = await historyResponse.json();
                    const messages = historyData.messages.map(m => ({ role: m.role, content: m.content }));
                    const response = await fetch(`${API_BASE}/chat`, {
                        method: 'POST',
                        headers: { 'Content-Type': 'application/json' },
                        body: JSON.stringify({ messages, temperature: 0.7, top_p: 0.9 })
                    });
                    if (!response.ok) throw new Error('Chat API failed');
                    const data = await response.json();
                    if (!data.choices || !data.choices[0] || !data.choices[0].message) throw new Error('Invalid response format');
                    const assistantMessage = data.choices[0].message.content;
                    const assistantMessageObj = { role: 'assistant', content: assistantMessage };
                    try {
                        await fetch(`${API_BASE}/chat/history/${currentSessionId}`, {
                            method: 'POST',
                            headers: { 'Content-Type': 'application/json' },
                            body: JSON.stringify({ message: assistantMessageObj })
                        });
                    } catch (e) {
                        console.error('Failed to save assistant message:', e);
                    }
                    typingEl.remove();
                    const aiMessageEl = document.createElement('div');
                    aiMessageEl.className = 'message ai';
                    aiMessageEl.textContent = assistantMessage;
                    chatHistory.appendChild(aiMessageEl);
                } catch (error) {
                    typingEl.remove();
                    showError('Hiba történt az üzenet feldolgozásakor. Próbáld újra később.');
                    console.error('Chat error:', error);
                }
                chatHistory.scrollTop = chatHistory.scrollHeight;
            }

            function updateSendButton() {
                const input = document.getElementById('message-input');
                const sendButton = document.getElementById('send-button');
                sendButton.disabled = !input.value.trim();
            }

            function showResearchModal() {
                document.getElementById('research-options-modal-overlay').classList.add('visible');
            }

            function hideResearchModal() {
                document.getElementById('research-options-modal-overlay').classList.remove('visible');
            }

            async function submitResearchTask() {
                const goalInput = document.getElementById('research-goal');
                const goal = goalInput.value.trim();
                if (!goal) {
                    showError('Kutatási cél megadása kötelező');
                    return;
                }
                const searchType = document.getElementById('search-type').value;
                const startDate = document.getElementById('start-published-date').value;
                const endDate = document.getElementById('end-published-date').value;
                const includeDomains = document.getElementById('include-domains').value;
                const fullText = document.getElementById('full-text').checked;
                const aiSummary = document.getElementById('ai-summary').checked;
                try {
                    const response = await fetch(`${API_BASE}/research/create`, {
                        method: 'POST',
                        headers: { 'Content-Type': 'application/json' },
                        body: JSON.stringify({
                            goal,
                            search_type: searchType,
                            start_published_date: startDate,
                            end_published_date: endDate,
                            include_domains: includeDomains,
                            full_text: fullText,
                            ai_summary: aiSummary
                        })
                    });
                    if (!response.ok) throw new Error('Failed to create research task');
                    const data = await response.json();
                    currentResearchId = data.task_id;
                    hideResearchModal();
                    showResearchView();
                    pollResearchStatus();
                } catch (error) {
                    showError('Hiba a kutatási feladat indításakor');
                    console.error('Research creation error:', error);
                }
            }

            function showResearchView() {
                document.getElementById('chat-view').classList.add('research-active');
                document.getElementById('research-view').classList.add('visible');
            }

            function hideResearchView() {
                document.getElementById('chat-view').classList.remove('research-active');
                document.getElementById('research-view').classList.remove('visible');
                if (statusInterval) clearInterval(statusInterval);
            }

            async function pollResearchStatus() {
                if (statusInterval) clearInterval(statusInterval);
                statusInterval = setInterval(async () => {
                    try {
                        const response = await fetch(`${API_BASE}/research/${currentResearchId}`);
                        if (!response.ok) throw new Error('Failed to fetch status');
                        const task = await response.json();
                        updateResearchUI(task);
                        if (task.status === 'completed' || task.status === 'error') {
                            clearInterval(statusInterval);
                        }
                    } catch (error) {
                        console.error('Status poll error:', error);
                    }
                }, 1000);
            }

            function updateResearchUI(task) {
                document.getElementById('research-title').textContent = task.goal.substring(0, 50);
                const agentGrid = document.getElementById('agent-grid');
                agentGrid.innerHTML = '';
                task.sub_agents.forEach((agent, index) => {
                    const agentCard = document.createElement('div');
                    agentCard.className = 'agent-card';
                    agentCard.innerHTML = `
                        <svg class="donut agent-progress-donut" viewBox="0 0 40 40">
                            <circle class="donut-bg" cx="20" cy="20" r="15"></circle>
                            <circle class="donut-fg" cx="20" cy="20" r="15" style="stroke-dashoffset: ${100 - task.progress}"></circle>
                        </svg>
                        <div class="agent-card-info">
                            <div class="agent-card-title">${agent.name}</div>
                            <div class="agent-card-status">${agent.status}</div>
                        </div>
                    `;
                    agentGrid.appendChild(agentCard);
                });
                const sourcesList = document.getElementById('sources-list');
                sourcesList.innerHTML = '';
                if (task.sources && task.sources.length > 0) {
                    task.sources.forEach((source, index) => {
                        const sourceItem = document.createElement('div');
                        sourceItem.className = 'similar-link-item';
                        sourceItem.innerHTML = `
                            <div class="icon-placeholder">
                                <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                                    <path d="M10 13a5 5 0 0 0 7.54.54l3-3a5 5 0 0 0-7.07-7.07l-1.72 1.71"></path>
                                </svg>
                            </div>
                            <div class="item-text">
                                <div class="item-title">${source.title}</div>
                                <div class="item-url">${source.url}</div>
                            </div>
                        `;
                        sourcesList.appendChild(sourceItem);
                    });
                } else {
                    sourcesList.innerHTML = '<div style="color: var(--text-secondary); text-align: center;">Források gyűjtése folyamatban...</div>';
                }
                const reportContent = document.getElementById('report-content');
                if (task.report) {
                    reportContent.textContent = task.report;
                } else {
                    reportContent.textContent = 'Jelentés összeállítása folyamatban...';
                }
            }

            document.getElementById('message-input').addEventListener('input', updateSendButton);
            document.getElementById('send-button').addEventListener('click', sendMessage);
            document.getElementById('message-input').addEventListener('keypress', function(e) {
                if (e.key === 'Enter' && !e.shiftKey) {
                    e.preventDefault();
                    sendMessage();
                }
            });
            document.getElementById('add-button').addEventListener('click', function() {
                const menu = document.getElementById('action-popup-menu');
                menu.classList.toggle('visible');
            });
            document.getElementById('menu-research').addEventListener('click', function() {
                document.getElementById('action-popup-menu').classList.remove('visible');
                showResearchModal();
            });
            document.getElementById('toggle-advanced-options').addEventListener('click', function() {
                const container = document.getElementById('advanced-options-container');
                container.style.display = container.style.display === 'none' ? 'block' : 'none';
            });
            document.getElementById('submit-research-task').addEventListener('click', submitResearchTask);
            document.getElementById('cancel-research-task').addEventListener('click', hideResearchModal);
            document.getElementById('research-back-button').addEventListener('click', hideResearchView);
            window.addEventListener('load', initBackground);
            updateSendButton();
        })();
    </script>
</body>
</html>"""
